 readonly TextBox frequencyInput=new(){Width=112,Height=26,Text="14.074.000",FontWeight=FontWeights.Bold,HorizontalContentAlignment=HorizontalAlignment.Center};readonly CheckBox autoCat=new(){Content="AUTO CAT",IsChecked=true};public bool AutoCatEnabled=>autoCat.IsChecked==true;public double ManualFrequencyMhz=>double.TryParse(frequencyInput.Text.Replace(".","").Replace(",",""),out var raw)?raw/1_000_000d:14.074;public void SetFrequency(double mhz){frequencyInput.Text=(mhz*1_000_000).ToString("000000000").Insert(3,".").Insert(7,".");}
 public Ft8AdvancedPanel(ObservableCollection<Ft8Signal> decoded,string call,string grid,Action startEngine,Action stopEngine,Action clearMessages,Action<bool,bool> setAutoArm)
 {InitializeComponent();BuildMenuHeader();AddFrequencyControl();StyleMenuItems(this);WireFrontPanelControls();AddNumericSpinners();var bottomButtons=FindChild<UniformGrid>(this);if(bottomButtons!=null)bottomButtons.Columns=4;LabelSliders();all=decoded;start=startEngine;stop=stopEngine;clear=clearMessages;autoArm=setAutoArm;AllMessages.ItemsSource=all;RxMessages.ItemsSource=rx;StationCall.Text=call;StationGrid.Text=grid;timer=new(){Interval=TimeSpan.FromSeconds(1)};timer.Tick+=(_,_)=>{var culture=useEnglish?System.Globalization.CultureInfo.GetCultureInfo("en-US"):System.Globalization.CultureInfo.GetCultureInfo("nb-NO");UtcClock.Text=DateTime.UtcNow.ToString("dd MMM yyyy  HH:mm:ss 'UTC'",culture);CpuText.Text=useEnglish?$"CPU  •  DECODED {all.Count}":$"CPU  •  DEKODET {all.Count}";if(all.Count>0&&rx.Count==0)rx.Add(all[0]);DrawWaterfall();};timer.Start();Loaded+=(_,_)=>{DrawScale();DrawWaterfall();DrawFrequencyMarkers();};}
