   int index=parent.Children.IndexOf(box);if(index<0)continue;int step=(box==RxHz||box==TxHz)?5:1;
   var arrows=new Grid{Width=18,Height=27,Margin=new Thickness(-2,2,2,2),ToolTip=$"Juster med ±{step}"};arrows.RowDefinitions.Add(new RowDefinition());arrows.RowDefinitions.Add(new RowDefinition());
   RepeatButton Arrow(string text,int delta,int row){var b=new RepeatButton{Content=text,FontSize=7,FontWeight=FontWeights.Bold,Padding=new Thickness(0),Margin=new Thickness(0),MinHeight=0,Background=new SolidColorBrush(Color.FromRgb(16,55,82)),Foreground=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(63,174,220)),BorderThickness=new Thickness(1),Delay=350,Interval=75};b.Click+=(_,_)=>AdjustNumeric(box,delta);Grid.SetRow(b,row);return b;}
