 void MenuClick(object sender,RoutedEventArgs e)
 {
  if(sender is not MenuItem m)return;string text=string.IsNullOrWhiteSpace(m.Uid)?m.Header?.ToString()??"":m.Uid,group=m.Tag?.ToString()??"";
  if(text=="Avslutt"){Window.GetWindow(this)?.Close();return;}
  if(text=="Vis logg …"){if(Window.GetWindow(this) is MainWindow main)main.MainTabs.SelectedIndex=1;return;}
  if(text.Contains("Lydkort")||text.Contains("Spillkontroll")||text.Contains("Opptakskontroll")){NavigateRequested?.Invoke("LYDKORT");return;}
  if(text.Contains("Radio / CAT")||text.Contains("Radio- og frekvens")){NavigateRequested?.Invoke("RADIO");return;}
  if(text.Contains("Nettverkskonfigurasjon")||text.Contains("automatisk logginformasjon")){NavigateRequested?.Invoke("LOGGSYNK");return;}
  if(text=="HamNavigator-hjelp"||text=="Tastatursnarveier"){NavigateRequested?.Invoke("BRUKSANVISNING");return;}
  if(text=="Om HamNavigator"){MessageBox.Show(useEnglish?"HamNavigator\nDesigned and programmed by Stian Bjerkan • LB7YK\n\nMSHV menus mapped against the official MSHV 2.76.6 source code.":"HamNavigator\nDesignet og programmert av Stian Bjerkan • LB7YK\n\nMSHV-menyer kartlagt mot offisiell MSHV 2.76.6-kildekode.",useEnglish?"About HamNavigator":"Om HamNavigator");return;}
  if(group=="Modus"){SelectOnly(m);Txing.Text=(useEnglish?"Mode: ":"Modus: ")+text.Split('•')[0].Trim();return;}
  if(group=="Bånd"){SelectOnly(m);Txing.Text=(useEnglish?"Band: ":"Bånd: ")+text;SetBandFrequency(text);return;}
  if(group=="Språk"){SelectOnly(m);ApplyLanguage(text);return;}
  if(group=="Palett"){if(text.Contains("Rediger")){ShowSettings("WATERFALL");return;}SelectOnly(m);DrawWaterfall();return;}
  if(group=="Decode"){Txing.Text=(useEnglish?"Decoder: ":"Dekoder: ")+Translate(text,useEnglish);return;}
  if(text=="Vis/skjul waterfall"){Waterfall.Visibility=m.IsChecked?Visibility.Visible:Visibility.Collapsed;return;}
  string page=text switch{"Makroer …"=>"MELDINGER","Tekstmarkering …"=>"WATERFALL","Generer meldinger for testtoner …"=>"TID / TX","Tidssynkronisering …"=>"TID / TX","Vis astronomiske data …"=>"TID / TX","Filtre for dekodeliste • FT …"=>"DEKODER","Multi Answering Auto Seq • DXpedition"=>"AUTO SEQ","Multi Answering Auto Seq • Standard"=>"AUTO SEQ",_=>""};
  if(page.Length>0){ShowSettings(page);return;}
  if(m.IsCheckable){Txing.Text=$"{Translate(text,useEnglish)}: {(useEnglish?(m.IsChecked?"ON":"OFF"):(m.IsChecked?"PÅ":"AV"))}";return;}
  MessageBox.Show(useEnglish?$"“{Translate(text,true)}” is in the correct MSHV menu position, but its HamNavigator dialog has not yet been implemented.":$"«{text}» er lagt på korrekt plass som i MSHV, men den tilhørende HamNavigator-dialogen er ennå ikke implementert.","HamNavigator");
 }
 void ShowSettings(string page){var window=new AdvancedFt8SettingsWindow(page){Owner=Window.GetWindow(this)};if(useEnglish)ApplyTranslations(window,true);window.ShowDialog();}
 void ApplyLanguage(string language)
 {
  if(language is not ("Norsk" or "English")){MessageBox.Show($"Språkpakken for {language} er synlig fordi menyen følger MSHV, men den er ikke oversatt i HamNavigator ennå. Norsk og English er aktive språkpakker.","HamNavigator • språk");return;}
  useEnglish=language=="English";EnglishActive=useEnglish;DependencyObject root=Window.GetWindow(this) is Window window?window:this;ApplyTranslations(root,useEnglish);if(Window.GetWindow(this) is MainWindow languageWindow)languageWindow.RefreshDynamicLanguage();if(useEnglish&&Window.GetWindow(this) is MainWindow main&&main.Footer.Text.StartsWith("GridTracker sentrert på"))main.Footer.Text=main.Footer.Text.Replace("GridTracker sentrert på","GridTracker centered on");else if(!useEnglish&&Window.GetWindow(this) is MainWindow norsk&&norsk.Footer.Text.StartsWith("GridTracker centered on"))norsk.Footer.Text=norsk.Footer.Text.Replace("GridTracker centered on","GridTracker sentrert på");Txing.Text=useEnglish?"Language: English":"Språk: Norsk";
 }
 static string Translate(string value,bool english)
 {
  if(english)return English.TryGetValue(value,out var translated)?translated:value;foreach(var pair in English)if(pair.Value==value)return pair.Key;return value;
 }
 public static string UiText(string norwegian)=>Translate(norwegian,EnglishActive);
 static void ApplyTranslations(DependencyObject root,bool english)
 {
  switch(root)
  {
   case Window window when !string.IsNullOrWhiteSpace(window.Title):window.Title=Translate(window.Title,english);break;
   case DataGrid grid:foreach(var column in grid.Columns)if(column.Header is string value)column.Header=Translate(value,english);break;
   case TextBlock text when !string.IsNullOrWhiteSpace(text.Text):text.Text=Translate(text.Text,english);break;
   case HeaderedItemsControl header when header.Header is string value:header.Header=Translate(value,english);break;
   case HeaderedContentControl header when header.Header is string value:header.Header=Translate(value,english);break;
   case ContentControl content when content.Content is string value:content.Content=Translate(value,english);break;
  }
  if(root is FrameworkElement element&&element.ToolTip is string tip)element.ToolTip=Translate(tip,english);
  foreach(var child in LogicalTreeHelper.GetChildren(root))if(child is DependencyObject dependency)ApplyTranslations(dependency,english);
 }
