 static T? FindChild<T>(DependencyObject root) where T:DependencyObject{foreach(var item in LogicalTreeHelper.GetChildren(root)){if(item is T hit)return hit;if(item is DependencyObject child&&FindChild<T>(child) is T nested)return nested;}return null;}
