 void LabelSliders(){string[] names={"WF GAIN","DT","DF TOL","RX","TX"};var sliders=FindChildren<Slider>(this).ToArray();for(int i=0;i<sliders.Length&&i<names.Length;i++){var slider=sliders[i];slider.ToolTip=names[i];if((slider==RxLevel||slider==TxLevel))continue;if(slider.Orientation==Orientation.Vertical&&slider.Parent is Grid g){var label=new TextBlock{Text=names[i],Foreground=new SolidColorBrush(Color.FromRgb(98,223,255)),Background=new SolidColorBrush(Color.FromArgb(210,7,17,31)),FontSize=9,FontWeight=FontWeights.Bold,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Top,Padding=new Thickness(2,1,2,1)};Grid.SetColumn(label,Grid.GetColumn(slider));Grid.SetRow(label,Grid.GetRow(slider));Panel.SetZIndex(label,3);g.Children.Add(label);}}}
 void ScaleChanged(object s,SizeChangedEventArgs e)=>DrawScale();void DrawScale(){if(ScaleCanvas==null)return;ScaleCanvas.Children.Clear();double w=ScaleCanvas.ActualWidth;for(int hz=0;hz<=3200;hz+=100){double x=hz/3200d*w;ScaleCanvas.Children.Add(new Line{X1=x,X2=x,Y1=hz%500==0?8:17,Y2=28,Stroke=Brushes.Black,StrokeThickness=1});if(hz%500==0){var t=new TextBlock{Text=hz.ToString(),Foreground=Brushes.Black,FontSize=10};Canvas.SetLeft(t,x+2);ScaleCanvas.Children.Add(t);}}}
 void DrawWaterfall(){if(Waterfall==null||ActualWidth<20)return;int w=Math.Max(400,(int)ActualWidth),h=180;var p=new byte[w*h*4];var now=DateTime.UtcNow.Millisecond;double tune=WaterfallTune?.Value??50,contrast=(WaterfallContrast?.Value??12)/12d;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*4;double sig=Math.Exp(-Math.Pow((x-w*.46)/18,2))+0.7*Math.Exp(-Math.Pow((x-w*.68)/10,2));double baseline=(tune-50)*1.8,noise=((x*13+y*7+now/10)%18)*contrast;p[i]=(byte)Math.Clamp(15+baseline+noise+sig*230*contrast,0,255);p[i+1]=(byte)Math.Clamp(8+baseline+noise+sig*150*contrast,0,255);p[i+2]=(byte)Math.Clamp(20+baseline+noise+sig*30*contrast,0,255);p[i+3]=255;}var b=new WriteableBitmap(w,h,96,96,PixelFormats.Bgra32,null);b.WritePixels(new Int32Rect(0,0,w,h),p,w*4,0);Waterfall.Source=b;if(Waterfall2!=null)Waterfall2.Source=b.Clone();DrawFrequencyMarkers();}
