 void ToggleDisplayMode(object s,RoutedEventArgs e){bool two=Waterfall2.Visibility!=Visibility.Visible;Waterfall2.Visibility=two?Visibility.Visible:Visibility.Collapsed;SecondDisplayRow.Height=two?new GridLength(1,GridUnitType.Star):new GridLength(0);DisplayModeButton.Content=two?"2D":"1D";DrawWaterfall();e.Handled=true;}
 int ReadAudioFrequency(TextBox box,int fallback)=>int.TryParse(box.Text,out var hz)?Math.Clamp(hz,0,3200):fallback;
 void SetBothMarkers(int hz){hz=Math.Clamp(hz,0,3200);syncingMarkers=true;RxHz.Text=hz.ToString();TxHz.Text=hz.ToString();lastRxHz=lastTxHz=hz;syncingMarkers=false;DrawFrequencyMarkers();}
 bool MarkersLocked()=>FindChildren<CheckBox>(this).FirstOrDefault(x=>(x.Content?.ToString()??"")=="LTR")?.IsChecked==true;
 void DrawFrequencyMarkers()
 {
  if(Overlay==null||Overlay.ActualWidth<=1)return;Overlay.Children.Clear();int rxHz=ReadAudioFrequency(RxHz,1500),txHz=ReadAudioFrequency(TxHz,1500);double h=Math.Max(1,Overlay.ActualHeight),rxX=rxHz/3200d*Overlay.ActualWidth,txX=txHz/3200d*Overlay.ActualWidth;
  void Marker(double x,Brush color,double dash){Overlay.Children.Add(new Line{X1=x-dash,X2=x-dash,Y1=0,Y2=h,Stroke=Brushes.Black,StrokeThickness=4});Overlay.Children.Add(new Line{X1=x-dash,X2=x-dash,Y1=0,Y2=h,Stroke=color,StrokeThickness=2});var tri=new Polygon{Fill=color,Points=new PointCollection{new(x-dash-6,0),new(x-dash+6,0),new(x-dash,9)}};Overlay.Children.Add(tri);}
  Marker(rxX,Brushes.LimeGreen,rxHz==txHz?-2:0);Marker(txX,Brushes.OrangeRed,rxHz==txHz?2:0);RxMarker.Text=$"RX: {rxHz} Hz   TX: {txHz} Hz";
 }
 void SetWaterfallFrequency(Point point,bool tx)
 {
  if(Overlay.ActualWidth<=1)return;int hz=(int)Math.Round(Math.Clamp(point.X,0,Overlay.ActualWidth)/Overlay.ActualWidth*3200/5d)*5;hz=Math.Clamp(hz,0,3200);if(tx)TxHz.Text=hz.ToString();else RxHz.Text=hz.ToString();lastAdjustedTx=tx;DrawFrequencyMarkers();
 }
 void WaterfallMouseDown(object sender,MouseButtonEventArgs e)
 {
  draggingWaterfall=true;draggingTx=e.ChangedButton==MouseButton.Right||(Keyboard.Modifiers&ModifierKeys.Shift)!=0;WaterfallHost.CaptureMouse();SetWaterfallFrequency(e.GetPosition(Overlay),draggingTx);if(e.ClickCount>=2){int hz=ReadAudioFrequency(draggingTx?TxHz:RxHz,1500);syncingMarkers=true;RxHz.Text=hz.ToString();TxHz.Text=hz.ToString();lastRxHz=lastTxHz=hz;syncingMarkers=false;DrawFrequencyMarkers();}e.Handled=true;
 }
 void WaterfallMouseMove(object sender,MouseEventArgs e){if(draggingWaterfall)SetWaterfallFrequency(e.GetPosition(Overlay),draggingTx);}
 void WaterfallMouseUp(object sender,MouseButtonEventArgs e){draggingWaterfall=false;WaterfallHost.ReleaseMouseCapture();e.Handled=true;}
 void WaterfallMouseWheel(object sender,MouseWheelEventArgs e){var box=lastAdjustedTx?TxHz:RxHz;int hz=ReadAudioFrequency(box,1500)+(e.Delta>0?5:-5);box.Text=Math.Clamp(hz,0,3200).ToString();e.Handled=true;}
 void FrequencyTextChanged(object sender,TextChangedEventArgs e)
 {
  if(RxHz==null||TxHz==null)return;int rx=ReadAudioFrequency(RxHz,lastRxHz),tx=ReadAudioFrequency(TxHz,lastTxHz);if(!syncingMarkers&&MarkersLocked()){syncingMarkers=true;if(ReferenceEquals(sender,RxHz)){int delta=rx-lastRxHz;tx=Math.Clamp(lastTxHz+delta,0,3200);TxHz.Text=tx.ToString();}else if(ReferenceEquals(sender,TxHz)){int delta=tx-lastTxHz;rx=Math.Clamp(lastRxHz+delta,0,3200);RxHz.Text=rx.ToString();}syncingMarkers=false;}lastRxHz=ReadAudioFrequency(RxHz,rx);lastTxHz=ReadAudioFrequency(TxHz,tx);DrawFrequencyMarkers();
 }
 void SaveDisplayClick(object sender,RoutedEventArgs e)
 {
  string which=(sender as Button)?.Content?.ToString()?.EndsWith("2")==true?"2":"1";var selectedDisplay=which=="2"&&Waterfall2.Visibility==Visibility.Visible?Waterfall2:Waterfall;if(selectedDisplay.Source is not BitmapSource bitmap)return;var dialog=new Microsoft.Win32.SaveFileDialog{Title=useEnglish?$"Save display {which}":$"Lagre display {which}",Filter=useEnglish?"PNG image (*.png)|*.png":"PNG-bilde (*.png)|*.png",FileName=$"HamNavigator-display-{which}-{DateTime.Now:yyyyMMdd-HHmmss}.png"};if(dialog.ShowDialog(Window.GetWindow(this))!=true)return;var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var stream=System.IO.File.Create(dialog.FileName);encoder.Save(stream);Txing.Text=useEnglish?$"DISPLAY {which} SAVED":$"DISPLAY {which} LAGRET";
 }
 void MonitorClick(object s,RoutedEventArgs e){start();Txing.Text=useEnglish?"MONITOR ON":"MONITOR PÅ";}void StopMonitorClick(object s,RoutedEventArgs e){stop();Txing.Text=useEnglish?"MONITOR OFF":"MONITOR AV";}void DecodeClick(object s,RoutedEventArgs e){start();}void ClearClick(object s,RoutedEventArgs e){clear();rx.Clear();}void ClearRxClick(object s,RoutedEventArgs e)=>rx.Clear();void HaltClick(object s,RoutedEventArgs e){stop();DxCall.Clear();DxGrid.Clear();Txing.Text=useEnglish?"QSO RESET":"QSO AVSLUTTET";}void StopTxClick(object s,RoutedEventArgs e){Arm.IsChecked=false;autoArm(AutoNext.IsChecked==true,false);Txing.Text=useEnglish?"TX STOPPED":"TX STOPPET";}void TuneClick(object s,RoutedEventArgs e)=>MessageBox.Show(useEnglish?"Tune requires a completed CAT/PTT driver and is safety locked.":"Tune krever ferdig CAT/PTT-driver og er sikkerhetssperret.","FT8 Tune");
 void GenerateClick(object s,RoutedEventArgs e){TxList.Items.Clear();string me=StationCall.Text.Trim().ToUpper(),dx=DxCall.Text.Trim().ToUpper(),g=StationGrid.Text.Trim().ToUpper(),r=Report.Text.Trim();foreach(var m in new[]{$"CQ {me} {g}",$"{dx} {me} {g}",$"{dx} {me} {r}",$"{dx} {me} R{r}",$"{dx} {me} RRR",$"{dx} {me} 73"}){var call=m.StartsWith("CQ ",StringComparison.OrdinalIgnoreCase)?me:dx;TxList.Items.Add(new TxQueueRow(call,"—",TxHz.Text,m));}TxList.SelectedIndex=0;QueueTab.Header=useEnglish?$"Queue {TxList.Items.Count}":$"Kø {TxList.Items.Count}";}void AutoClick(object s,RoutedEventArgs e){AutoNext.IsChecked=!(AutoNext.IsChecked==true);AutoButton.Content=AutoNext.IsChecked==true?(useEnglish?"AUTO IS ON":"AUTO ER PÅ"):(useEnglish?"AUTO IS OFF":"AUTO ER AV");autoArm(AutoNext.IsChecked==true,Arm.IsChecked==true);}void SendSelectedClick(object s,RoutedEventArgs e){autoArm(AutoNext.IsChecked==true,Arm.IsChecked==true);var message=TxList.SelectedItem is TxQueueRow row?row.Message:TxList.SelectedItem?.ToString()??"";Txing.Text=Arm.IsChecked==true?$"TXing: {message}":(useEnglish?"TX LOCKED • arm transmit":"TX SPERRET • armer sending");}
